-- ===============================================================
-- Flyway Migration V13: Rebuild Exercise-to-Media Pipeline from Scratch
-- Strict 1-to-1 fidelity: 189 verified RapidAPI workouts, each with its OWN distinct video
-- Zero video sharing between workouts. Non-dataset exercises use built-in SVG mannequin.
-- ===============================================================

-- 1. Add tracking columns to exercises table
ALTER TABLE exercises ADD COLUMN IF NOT EXISTS source VARCHAR(100);
ALTER TABLE exercises ADD COLUMN IF NOT EXISTS external_id VARCHAR(100);
ALTER TABLE exercises ADD COLUMN IF NOT EXISTS media_checksum VARCHAR(64);
ALTER TABLE exercises ADD COLUMN IF NOT EXISTS match_method VARCHAR(50);
ALTER TABLE exercises ADD COLUMN IF NOT EXISTS review_status VARCHAR(50) DEFAULT 'no-media';
ALTER TABLE exercises ADD COLUMN IF NOT EXISTS legacy_media_url VARCHAR(1000);
ALTER TABLE exercises ADD COLUMN IF NOT EXISTS legacy_poster_url VARCHAR(1000);
CREATE UNIQUE INDEX IF NOT EXISTS idx_exercises_source_external_id ON exercises(source, external_id);

-- 2. Archive previous media URLs and wipe unverified/guessed media from all exercises
CREATE TABLE IF NOT EXISTS exercise_media_backup AS SELECT id, name, media_url, poster_url, media_provider, media_type, attribution FROM exercises;
UPDATE exercises SET legacy_media_url = media_url, legacy_poster_url = poster_url WHERE legacy_media_url IS NULL;
UPDATE exercises SET media_url = NULL, poster_url = NULL, media_provider = 'builtin', media_type = 'animation', review_status = 'no-media', match_method = 'manual';

-- 3. Import all 189 verified RapidAPI workouts with exact 1-to-1 media fidelity
