MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_checksum, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Standing Calf Raise', 'CALVES', 'SOLEUS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Place your feet shoulder-width apart and position your toes straight ahead or slightly outwards.', '["Place your feet shoulder-width apart and position your toes straight ahead or slightly outwards.","Slowly raise your heels off the floor by pushing down through the balls of both feet while exhaling, ensuring your abdominal muscles are engaged and your back is straight.","Pause for a moment when your calves are fully contracted and you''re balancing on the balls of your feet.","Gradually lower your heels back to the ground to the starting position while inhaling, ensuring that you maintain control throughout the movement. Repeat this for the desired number of repetitions."]', '["Using momentum or rushing eccentric phase.","Failing to brace core and maintain spinal alignment."]', 3, '8-12', false, 'ExerciseDB via AscendAPI', 'exercisedb-ascendapi', 'exr_41n2hQtaWxPLNFwX', '/media/exercises/dumbbell_standing_calf_raise.mp4', '/media/posters/dumbbell_standing_calf_raise.jpg', '54bc60e9adb4fea00c933db32624981d9b4bfbdb6e3fd977adc0db85d735b438', 'licensed', 'video', 'verified', 'dataset-record');
