MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_checksum, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell One Arm Bent-over Row', 'BACK', 'BRACHIORADIALIS,PECTORALIS MAJOR STERNAL HEAD,POSTERIOR DELTOID', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Bend your knees slightly and lean forward from your waist until your torso is almost parallel to the floor, making sure to keep your back straight.', '["Bend your knees slightly and lean forward from your waist until your torso is almost parallel to the floor, making sure to keep your back straight.","Hold onto the bench with your free hand for support, and let the hand holding the dumbbell hang down from your shoulder.","Pull the dumbbell up towards your waist, keeping your elbow close to your body and squeezing your shoulder blades together at the top of the movement.","Lower the dumbbell back down in a controlled manner to the starting position, and repeat the exercise for your desired number of reps before switching to the other arm."]', '["Using momentum or rushing eccentric phase.","Failing to brace core and maintain spinal alignment."]', 3, '8-12', false, 'ExerciseDB via AscendAPI', 'exercisedb-ascendapi', 'exr_41n2hY9EdwkdGz9a', '/media/exercises/dumbbell_one_arm_bent_over_row.mp4', '/media/posters/dumbbell_one_arm_bent_over_row.jpg', 'cfcef7131f8b8d0dfaf421980324e9e0e9e1492b186060f37ad135c7a3edf4b8', 'licensed', 'video', 'verified', 'dataset-record');
